import planarity

pg = planarity.PGraph(g)
pg.embed_drawplanar()
g = planarity.networkx_graph(pg)


node_labels = {}
xs = []
ys = []

nodes_by_height = {}
node_xs_by_y = {}
node_xs_ys = {}
node_lefts_rights = {}

for node, data in g.nodes(data=True):
    y = data['pos']
    xb = data['start']
    xe = data['end']
    x = int((xe + xb) / 2.)

    node_labels[node] = (x, y)
    xs.extend([xb, xe])
    ys.append(y)

